import * as THREE from './vendor/three.module.js';
export const TILE=4,SIZE=48,HALF=96;
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n)),smooth=t=>t*t*(3-2*t);
function hash(x,y,seed){let v=Math.imul(x,374761393)+Math.imul(y,668265263)+seed*31;v=Math.imul(v^(v>>>13),1274126177);return((v^(v>>>16))>>>0)/4294967295}
function noise(x,y,seed){const a=Math.floor(x),b=Math.floor(y),u=smooth(x-a),v=smooth(y-b);return THREE.MathUtils.lerp(THREE.MathUtils.lerp(hash(a,b,seed),hash(a+1,b,seed),u),THREE.MathUtils.lerp(hash(a,b+1,seed),hash(a+1,b+1,seed),u),v)}
function wetTile(w,x,y){if(x>=0&&y>=0&&x<SIZE&&y<SIZE)return w.tiles[y*SIZE+x].ground==='water'?1:0;if(w.terrain==='river')return Math.abs(x-(34+Math.sin(y/7+w.seed%9)*3))<2.3?1:0;if(w.terrain==='islands')return Math.sin(x/7)+Math.cos(y/8)+Math.sin((x+y)/9)>1.05?1:0;return 0}
const waterFields=new WeakMap();
function field(w){if(waterFields.has(w))return waterFields.get(w);const f=new Float32Array(52*52),weights=[.18,.64,.18];for(let y=-2;y<50;y++)for(let x=-2;x<50;x++){let v=0;for(let j=-1;j<=1;j++)for(let i=-1;i<=1;i++)v+=wetTile(w,x+i,y+j)*weights[i+1]*weights[j+1];f[(y+2)*52+x+2]=v}waterFields.set(w,f);return f}
export function wetness(w,x,z){const gx=(x+HALF)/TILE-.5,gy=(z+HALF)/TILE-.5;if(w.terrain==='river'){const distance=Math.abs(gx-(34+Math.sin(gy/7+w.seed%9)*3));return smooth(clamp((3.35-distance)/2.1,0,1))}if(w.terrain==='islands'){const level=Math.sin(gx/7)+Math.cos(gy/8)+Math.sin((gx+gy)/9);return smooth(clamp((level-.72)/.65,0,1))}return 0}
export function groundHeight(w,x,z){const water=wetness(w,x,z),inland=.3+noise(x*.012,z*.012,w.seed)*1.7+noise(x*.026,z*.026,w.seed+3)*.95+noise(x*.065,z*.065,w.seed+17)*.18;const edge=smooth(clamp((Math.hypot(x,z)-180)/260,0,1)),hills=edge*(noise(x*.006,z*.006,w.seed+8)*24+noise(x*.013,z*.013,w.seed+11)*8),bank=smooth(clamp(water*2.1,0,1));return inland*(1-bank)+hills*(1-smooth(clamp(water*4,0,1)))-bank*1.6;}
export function floorHeight(w,x,z){return Math.max(.2,groundHeight(w,x,z))}
export class Landscape{
constructor(view){this.view=view;this.group=new THREE.Group();view.scene.add(this.group);this.loader=new THREE.TextureLoader();this.assets={};this.ready=this.load();}
async load(){const defs=['grass-color','grass-normal','grass-rough','asphalt-color','asphalt-normal','asphalt-rough','brick-color','brick-normal','brick-rough'];await Promise.all(defs.map(async name=>{try{const t=await this.loader.loadAsync(new URL('./assets/'+name+'.jpg',import.meta.url).href);t.wrapS=t.wrapT=THREE.RepeatWrapping;t.anisotropy=this.view.renderer.capabilities.getMaxAnisotropy();if(name.endsWith('color'))t.colorSpace=THREE.SRGBColorSpace;this.assets[name]=t}catch(e){console.warn('Texture fallback:',name)}}));}
material(name,repeat=1,color='#ffffff'){const map=this.assets[name+'-color']?.clone(),normal=this.assets[name+'-normal']?.clone(),rough=this.assets[name+'-rough']?.clone();for(let t of [map,normal,rough])if(t){t.repeat.set(repeat,repeat);t.needsUpdate=true}return new THREE.MeshStandardMaterial({color,map:map||null,normalMap:normal||null,roughnessMap:rough||null,normalScale:new THREE.Vector2(.3,.3),roughness:.92});}
clear(){this.group.traverse(o=>{if(o.geometry)o.geometry.dispose();if(o.material){for(let m of Array.isArray(o.material)?o.material:[o.material]){if(m===this.leafMat||[...this.view.materials.values()].includes(m))continue;for(let k of ['map','normalMap','roughnessMap'])if(m[k]&&!Object.values(this.assets).includes(m[k]))m[k].dispose();m.dispose()}}});this.group.clear()}
build(w){this.clear();this.world=w;const geo=new THREE.PlaneGeometry(192,192,192,192);geo.rotateX(-Math.PI/2);const pos=geo.attributes.position,colors=[];for(let i=0;i<pos.count;i++){const x=pos.getX(i),z=pos.getZ(i),h=groundHeight(w,x,z),wet=wetness(w,x,z);pos.setY(i,h);const shade=.86+noise(x*.08,z*.08,w.seed)*.19;const col=new THREE.Color(wet>.08&&wet<.65?'#b6b19b':'#b8c5a0');col.multiplyScalar(shade);colors.push(col.r,col.g,col.b)}geo.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));geo.computeVertexNormals();const mat=this.material('grass',14,'#c0c4aa');mat.vertexColors=true;mat.normalScale.set(.55,.55);this.ground=new THREE.Mesh(geo,mat);this.ground.receiveShadow=true;this.group.add(this.ground);
const far=new THREE.PlaneGeometry(1100,1100,400,400);far.rotateX(-Math.PI/2);const fp=far.attributes.position;for(let i=0;i<fp.count;i++)fp.setY(i,groundHeight(w,fp.getX(i),fp.getZ(i))-.1);let ind=[];const arr=far.index.array;for(let i=0;i<arr.length;i+=3){let x=0,z=0;for(let j=0;j<3;j++){x+=fp.getX(arr[i+j])/3;z+=fp.getZ(arr[i+j])/3}if(Math.abs(x)>95||Math.abs(z)>95)ind.push(arr[i],arr[i+1],arr[i+2])}far.setIndex(ind);far.computeVertexNormals();const farColors=[];for(let i=0;i<fp.count;i++){const x=fp.getX(i),z=fp.getZ(i),wet=wetness(w,x,z),c=new THREE.Color('#b8c5a0').lerp(new THREE.Color('#b6b19b'),Math.min(1,wet*4));c.multiplyScalar(.92+.07*Math.sin(x*.17)*Math.cos(z*.13)+.035*Math.sin(x*.7+z*.43));farColors.push(c.r,c.g,c.b)}far.setAttribute('color',new THREE.Float32BufferAttribute(farColors,3));const fm=this.material('grass',80.2083,'#c0c4aa');fm.vertexColors=true;this.surroundings=new THREE.Mesh(far,fm);this.surroundings.receiveShadow=true;this.group.add(this.surroundings);
this.waterMaterial=new THREE.ShaderMaterial({uniforms:{time:{value:0},sun:{value:new THREE.Vector3(-.4,.75,.35)},night:{value:0}},vertexShader:`varying vec3 worldPos;varying vec3 viewDir;void main(){vec4 p=modelMatrix*vec4(position,1.);worldPos=p.xyz;viewDir=cameraPosition-p.xyz;gl_Position=projectionMatrix*viewMatrix*p;}`,fragmentShader:`precision highp float;uniform float time;uniform float night;uniform vec3 sun;varying vec3 worldPos;varying vec3 viewDir;void main(){vec2 p=worldPos.xz;float a=sin(p.x*1.8+p.y*.9+time*.7),b=cos(p.x*.7-p.y*2.2-time*.85);vec3 n=normalize(vec3(a*.065,1.,b*.08));vec3 v=normalize(viewDir);float fres=pow(1.-max(dot(v,n),0.),3.);float glint=pow(max(dot(reflect(-normalize(sun),n),v),0.),110.);float ripple=.5+.5*sin(p.x*.5+p.y*.8+time*.3);vec3 deep=mix(vec3(.10,.22,.24),vec3(.20,.32,.34),ripple*.3);vec3 c=mix(deep,vec3(.56,.67,.69),fres*.65)+glint*.6;c=mix(c,c*.32,night);gl_FragColor=vec4(c,1.);}`,side:THREE.DoubleSide});this.water=new THREE.Mesh(new THREE.PlaneGeometry(1100,1100),this.waterMaterial);this.water.rotation.x=-Math.PI/2;this.water.position.y=-.1;this.group.add(this.water);this.makeTrees(w);}
leafMaterial(){if(this.leafMat)return this.leafMat;const c=document.createElement('canvas');c.width=c.height=128;const ctx=c.getContext('2d');for(let i=0;i<380;i++){let a=i*2.39996,r=Math.sqrt(i/380)*59,x=64+Math.cos(a)*r,y=64+Math.sin(a)*r;ctx.fillStyle=['#6c8047','#70874d','#526a36','#8a9659'][i%4];ctx.beginPath();ctx.ellipse(x,y,2.3+(i%3),1.5+(i%2),a,0,Math.PI*2);ctx.fill()}const tex=new THREE.CanvasTexture(c);tex.colorSpace=THREE.SRGBColorSpace;this.leafMat=new THREE.MeshStandardMaterial({map:tex,alphaTest:.45,side:THREE.DoubleSide,roughness:1,envMapIntensity:.1});return this.leafMat}
makeTrees(w){const positions=[];w.tiles.forEach((t,i)=>{if(t.tree&&!t.type&&t.ground==='land'){const x=(i%48+.5)*4-96,z=(Math.floor(i/48)+.5)*4-96;for(let j=0;j<2;j++){const px=x+hash(i,j,w.seed)*3-1.5,pz=z+hash(j,i,w.seed)*3-1.5;if(wetness(w,px,pz)<.18)positions.push([px,pz,2.8+hash(i,j+3,w.seed)*2,i%4])}}});const trunk=new THREE.InstancedMesh(new THREE.CylinderGeometry(.045,.12,1,7),this.view.mat('#746958'),positions.length),leaves=new THREE.InstancedMesh(new THREE.PlaneGeometry(1,1),this.leafMaterial(),positions.length*24);const d=new THREE.Object3D();positions.forEach(([x,z,h,v],i)=>{const y=floorHeight(w,x,z);d.rotation.set(0,0,0);d.position.set(x,y+h*.43,z);d.scale.set(1,h*.85,1);d.updateMatrix();trunk.setMatrixAt(i,d.matrix);for(let j=0;j<24;j++){const a=j*2.399+i,r=(j%3)*h*.09;d.position.set(x+Math.cos(a)*r,y+h*.53+(j%5)*h*.09,z+Math.sin(a)*r);d.rotation.set((j%3-1)*.45,a,(j%2)*.25);const size=h*(.5+(j%4)*.03);d.scale.set(size,size*(j%2?.9:1.1),1);d.updateMatrix();leaves.setMatrixAt(i*24+j,d.matrix);const col=new THREE.Color(['#b9cba4','#95b09c','#c7cfa7','#acc294'][v]);leaves.setColorAt(i*24+j,col)}});trunk.castShadow=true;leaves.castShadow=true;leaves.receiveShadow=true;this.group.add(trunk,leaves);this.trees=[trunk,leaves]}

refreshTrees(w){for(let o of this.trees||[]){this.group.remove(o);o.dispose();o.geometry.dispose()}this.makeTrees(w)}
update(time,night){if(this.waterMaterial){this.waterMaterial.uniforms.time.value=time;this.waterMaterial.uniforms.night.value=night?1:0}}
}
